module RawFloat_FMA_1(
  input         clock,
                io_a_isZero,
                io_a_isInf,
                io_a_isNaN,
                io_a_sign,
  input  [5:0]  io_a_exp,
  input  [10:0] io_a_mantissa,
  input         io_b_isZero,
                io_b_isInf,
                io_b_isNaN,
                io_b_sign,
  input  [5:0]  io_b_exp,
  input  [10:0] io_b_mantissa,
  input         io_c_isZero,
                io_c_isInf,
                io_c_isNaN,
                io_c_sign,
  input  [8:0]  io_c_exp,
  input  [23:0] io_c_mantissa,
  output        io_out_isZero,
                io_out_isInf,
                io_out_isNaN,
                io_out_sign,
  output [8:0]  io_out_exp,
  output [25:0] io_out_mantissa
