  wire         io_out_isNaN_0;
  wire [52:0]  _shiftRightJam_io_out;
  wire         _shiftRightJam_io_sticky;
  wire [6:0]   prodExp_s1 = {io_a_exp[5], io_a_exp} + {io_b_exp[5], io_b_exp};
  wire         prodIsZero_s1 = io_a_isZero | io_b_isZero;
  wire [7:0]   _expDiff_s1_T = {prodExp_s1[6], prodExp_s1} + 8'h1B;
  wire [9:0]   expDiff_s1 =
    {{2{_expDiff_s1_T[7]}}, _expDiff_s1_T} - {io_c_exp[8], io_c_exp};
  wire [8:0]   alignShiftAmt_s1 =
    $signed(expDiff_s1) < 10'sh0 | prodIsZero_s1 ? 9'h0 : expDiff_s1[8:0];
  reg  [53:0]  adderOutAbs;
  reg          cGtProd2;
  reg  [9:0]   expDiff2;
  reg  [8:0]   alignShiftAmt2;
  reg          cSign2;
  reg  [8:0]   cExp2;
  reg          cIsZero2;
  reg          cIsInf2;
  reg          prodSign2;
  reg          prodIsZero2;
  reg  [6:0]   prodExp2;
  reg          hasNaN2;
  reg          prodHasInf2;
  reg          addInfInvalid2;
  reg          mulInfInvalid2;
