    _cAnchoredMantissa_T[54]
      ? _cAnchoredMantissa_T[54:0]
      : _cAnchoredMantissa_T[53]
          ? {_cAnchoredMantissa_T[53:0], 1'h0}
          : {_cAnchoredMantissa_T[52:0], 2'h0};
