  wire [4:0]   lzc =
    adderOutAbs[29]
      ? 5'h0
      : adderOutAbs[28]
          ? 5'h1
          : adderOutAbs[27]
              ? 5'h2
              : adderOutAbs[26]
                  ? 5'h3
                  : adderOutAbs[25]
                      ? 5'h4
                      : adderOutAbs[24]
                          ? 5'h5
                          : adderOutAbs[23]
                              ? 5'h6
                              : adderOutAbs[22]
                                  ? 5'h7
                                  : adderOutAbs[21]
                                      ? 5'h8
                                      : adderOutAbs[20]
                                          ? 5'h9
                                          : adderOutAbs[19]
                                              ? 5'hA
                                              : adderOutAbs[18]
                                                  ? 5'hB
                                                  : adderOutAbs[17]
                                                      ? 5'hC
                                                      : adderOutAbs[16]
                                                          ? 5'hD
                                                          : adderOutAbs[15]
                                                              ? 5'hE
                                                              : adderOutAbs[14]
                                                                  ? 5'hF
                                                                  : adderOutAbs[13]
                                                                      ? 5'h10
                                                                      : adderOutAbs[12]
                                                                          ? 5'h11
                                                                          : adderOutAbs[11]
                                                                              ? 5'h12
                                                                              : adderOutAbs[10]
                                                                                  ? 5'h13
                                                                                  : adderOutAbs[9]
                                                                                      ? 5'h14
                                                                                      : adderOutAbs[8]
                                                                                          ? 5'h15
                                                                                          : adderOutAbs[7]
                                                                                              ? 5'h16
                                                                                              : adderOutAbs[6]
                                                                                                  ? 5'h17
                                                                                                  : adderOutAbs[5]
                                                                                                      ? 5'h18
                                                                                                      : adderOutAbs[4]
                                                                                                          ? 5'h19
                                                                                                          : adderOutAbs[3]
