  wire [60:0]  _pAnchoredNormMantissa_T = {31'h0, adderOutAbs[29:0]} << lzc;
  wire         _io_out_isZero_T = cIsZero2 & prodIsZero2;
  assign io_out_isNaN_0 = hasNaN2 | addInfInvalid2 | mulInfInvalid2;
  wire         prodSign_s1 = io_a_sign ^ io_b_sign;
  wire         doSub = prodSign_s1 ^ io_c_sign;
  wire [53:0]  _addProd_T_1 =
    prodIsZero_s1
      ? 54'h0
      : {26'h0, {11'h0, io_a_mantissa} * {11'h0, io_b_mantissa}, 6'h0};
  wire [54:0]  _GEN = {1'h0, _shiftRightJam_io_out, _shiftRightJam_io_sticky};
  wire [54:0]  _pMinusC_T_4 = (doSub ? 55'h0 - _GEN : _GEN) + {1'h0, _addProd_T_1};
  wire         _mulInfInvalid2_T = io_a_isInf | io_b_isInf;
  always @(posedge clock) begin
    adderOutAbs <=
      _pMinusC_T_4[54]
        ? {_shiftRightJam_io_out, _shiftRightJam_io_sticky} - _addProd_T_1
        : _pMinusC_T_4[53:0];
    cGtProd2 <= _pMinusC_T_4[54];
    expDiff2 <= expDiff_s1;
    alignShiftAmt2 <= alignShiftAmt_s1;
    cSign2 <= io_c_sign;
    cExp2 <= io_c_exp;
    cIsZero2 <= io_c_isZero;
    cIsInf2 <= io_c_isInf;
    prodSign2 <= prodSign_s1;
    prodIsZero2 <= prodIsZero_s1;
    prodExp2 <= prodExp_s1;
    hasNaN2 <= io_a_isNaN | io_b_isNaN | io_c_isNaN;
    prodHasInf2 <= _mulInfInvalid2_T;
    addInfInvalid2 <= io_c_isInf & _mulInfInvalid2_T & doSub;
