  ShiftRightJam shiftRightJam (
    .io_in     ({io_c_isZero ? 24'h0 : io_c_mantissa, 29'h0}),
    .io_shamt  (alignShiftAmt_s1),
    .io_out    (_shiftRightJam_io_out),
    .io_sticky (_shiftRightJam_io_sticky)
  );
  assign io_out_isZero = _io_out_isZero_T | ~cAnchored & pAnchoredIsZero;
  assign io_out_isInf = ~io_out_isNaN_0 & (cIsInf2 | prodHasInf2);
  assign io_out_isNaN = io_out_isNaN_0;
  assign io_out_sign =
    cIsInf2
      ? cSign2
      : prodHasInf2
          ? prodSign2
          : _io_out_isZero_T
              ? cSign2 & prodSign2
              : ~(~cAnchored & pAnchoredIsZero) & (cGtProd2 ? cSign2 : prodSign2);
  assign io_out_exp =
    cAnchored
      ? (_cAnchoredMantissa_T[54]
           ? cExp2 + 9'h1
           : _cAnchoredMantissa_T[53] ? cExp2 : cExp2 - 9'h1)
      : {_pAnchoredExp_T_2[7], _pAnchoredExp_T_2};
  assign io_out_mantissa =
    cAnchored
      ? {cAnchoredNormMantissa[54:30], |(cAnchoredNormMantissa[29:0])}
      : {_pAnchoredNormMantissa_T[29:5], |(_pAnchoredNormMantissa_T[4:0])};
endmodule

module RawFloat_MulAddExp2_1(
  input         clock,
                reset,
                io_in_exp2,
                io_in_a_isZero,
                io_in_a_isInf,
                io_in_a_isNaN,
