     _gate_io_out_elemType_mantissa};
  reg  [31:0] expectedAcc;
  reg  [15:0] expectedElem;
  reg         expectedHit;
  reg         valid;
  always @(posedge clock) begin
    expectedAcc <= io_goldAcc_0;
    expectedElem <= io_goldElem_0;
    expectedHit <= _gold_io_out_exp2;
    if (reset)
      valid <= 1'h0;
    else
      valid <= ~reset;
  end // always @(posedge)
  FPMacUnit gold (
    .io_in_a_sign             (io_a[15]),
    .io_in_a_exp              (io_a[14:10]),
    .io_in_a_mantissa         (io_a[9:0]),
    .io_in_b_sign             (io_b[15]),
    .io_in_b_exp              (io_b[14:10]),
    .io_in_b_mantissa         (io_b[9:0]),
    .io_in_c_sign             (io_c[31]),
    .io_in_c_exp              (io_c[30:23]),
    .io_in_c_mantissa         (io_c[22:0]),
    .io_in_cmd                (io_exp2),
    .io_out_accType_sign      (_gold_io_out_accType_sign),
    .io_out_accType_exp       (_gold_io_out_accType_exp),
    .io_out_accType_mantissa  (_gold_io_out_accType_mantissa),
    .io_out_elemType_sign     (_gold_io_out_elemType_sign),
    .io_out_elemType_exp      (_gold_io_out_elemType_exp),
    .io_out_elemType_mantissa (_gold_io_out_elemType_mantissa),
    .io_out_exp2              (_gold_io_out_exp2)
  );
  FPMacUnit_1 gate (
    .clock                    (clock),
    .reset                    (reset),
    .io_in_a_sign             (io_a[15]),
    .io_in_a_exp              (io_a[14:10]),
    .io_in_a_mantissa         (io_a[9:0]),
    .io_in_b_sign             (io_b[15]),
    .io_in_b_exp              (io_b[14:10]),
    .io_in_b_mantissa         (io_b[9:0]),
    .io_in_c_sign             (io_c[31]),
    .io_in_c_exp              (io_c[30:23]),
    .io_in_c_mantissa         (io_c[22:0]),
    .io_in_cmd                (io_exp2),
    .io_out_accType_sign      (_gate_io_out_accType_sign),
    .io_out_accType_exp       (_gate_io_out_accType_exp),
    .io_out_accType_mantissa  (_gate_io_out_accType_mantissa),
    .io_out_elemType_sign     (_gate_io_out_elemType_sign),
    .io_out_elemType_exp      (_gate_io_out_elemType_exp),
    .io_out_elemType_mantissa (_gate_io_out_elemType_mantissa),
    .io_out_exp2              (_gate_io_out_exp2)
  );
  assign io_mismatch =
    valid
    & (expectedAcc != io_gateAcc_0 | expectedElem != io_gateElem_0
       | expectedHit != _gate_io_out_exp2);
  assign io_goldAcc = io_goldAcc_0;
  assign io_gateAcc = io_gateAcc_0;
  assign io_goldElem = io_goldElem_0;
  assign io_gateElem = io_gateElem_0;
  assign io_goldHit = _gold_io_out_exp2;
  assign io_gateHit = _gate_io_out_exp2;
endmodule

